diff --git a/check-image-model.mjs b/check-image-model.mjs
new file mode 100644
index 0000000..0f1317a
--- /dev/null
+++ b/check-image-model.mjs
@@ -0,0 +1,6 @@
+import fs from "fs";
+const src = fs.readFileSync(new URL("./index.js", import.meta.url), "utf8");
+if (src.includes("image-alpha-001")) throw new Error("old image model still present");
+if (!src.includes('model: "gpt-image-2.5-flare"')) throw new Error("new image model missing");
+if (!src.includes("b64_json")) throw new Error("b64_json not handled");
+console.log("ok");
