@@ -35,13 +35,14 @@ router.get("/image", async (ctx, next) => {
     const { prompt } = ctx.request.query;
     const res = await openai.createImage({
         // 对话模型
-        model: "image-alpha-001",
+        model: "gpt-image-2.5-flare",
         prompt: prompt,
-        size: "256x256",
+        size: "1024x1024",
         n: 1
     })
-    // 将生成的内容返回给客户端
-    var url = res.data.data[0].url
